// surfList1 is a []*Task as a list.
type surfList1 []*Task

func (l surfList1) Len() int               { return len(l) }
func (l surfList1) At(i int) cellite.Value { return surfTaskValue(l[i]) }

// surfList1Of is a list's value as a []*Task.
func surfList1Of(v cellite.Value) []*Task {
	l := v.List()
	if l == nil {
		return nil
	}
	out := make([]*Task, l.Len())
	for i := range out {
		out[i] = surfTaskOf(l.At(i))
	}
	return out
}

// surfList2 is a []string as a list.
type surfList2 []string

func (l surfList2) Len() int               { return len(l) }
func (l surfList2) At(i int) cellite.Value { return cellite.StringValue(string(l[i])) }

// surfList2Of is a list's value as a []string.
func surfList2Of(v cellite.Value) []string {
	l := v.List()
	if l == nil {
		return nil
	}
	out := make([]string, l.Len())
	for i := range out {
		out[i] = string(l.At(i).String())
	}
	return out
}

